/*
 * vnc_touch_bridge.c — Real-Time Remote Pointer to XDJ-AZ Touch Engine Bridge
 * Target: Armbian Linux (Amlogic S905X) & Embedded X11 Targets
 *
 * Translates X11 pointer events (ButtonPress, ButtonRelease, MotionNotify)
 * generated by x11vnc, noVNC HTML5 Web Remote, and xdotool on DISPLAY=:0
 * directly into Multi-Touch frames sent to /tmp/xdj_touch_inject.sock.
 *
 * Ensures JUCE receives adequate touch-down dwell time (minimum 60ms)
 * so that clicks reliably trigger UI buttons, tabs, waveform scrubs, and menus.
 */

#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <X11/Xlib.h>
#include <X11/Xproto.h>
#include <X11/extensions/record.h>

#define TARGET_TOUCH_SOCK    "/tmp/xdj_touch_inject.sock"
#define LOGICAL_WIDTH        1280
#define LOGICAL_HEIGHT       800
#define MIN_PRESS_HOLD_MS    60
#define LOG_TAG              "[vnc_touch_bridge] "

static volatile bool g_running = true;
static int g_sock_fd = -1;
static struct sockaddr_un g_target_addr;
static Display *g_ctrl_dpy = NULL;
static Display *g_data_dpy = NULL;
static XRecordContext g_ctx = 0;

static bool g_btn1_down = false;
static int g_last_x = LOGICAL_WIDTH / 2;
static int g_last_y = LOGICAL_HEIGHT / 2;
static uint64_t g_press_time_ms = 0;

static uint64_t get_time_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void send_touch(int x, int y, int touched) {
    if (g_sock_fd < 0) return;
    if (x < 0) x = 0;
    if (x >= LOGICAL_WIDTH) x = LOGICAL_WIDTH - 1;
    if (y < 0) y = 0;
    if (y >= LOGICAL_HEIGHT) y = LOGICAL_HEIGHT - 1;

    char buf[64];
    int len = snprintf(buf, sizeof(buf), "%d,%d,%d\n", x, y, touched);
    sendto(g_sock_fd, buf, len, 0, (struct sockaddr*)&g_target_addr, sizeof(g_target_addr));
}

static void record_callback(XPointer closure, XRecordInterceptData *data) {
    (void)closure;
    if (!data) return;

    if (data->category == XRecordFromServer) {
        xEvent *ev = (xEvent *)data->data;
        BYTE type = ev->u.u.type;

        if (type == ButtonPress) {
            BYTE button = ev->u.u.detail;
            if (button == 1) { /* Left Mouse Button */
                int x = ev->u.keyButtonPointer.rootX;
                int y = ev->u.keyButtonPointer.rootY;
                g_btn1_down = true;
                g_last_x = x;
                g_last_y = y;
                g_press_time_ms = get_time_ms();
                send_touch(x, y, 1);
            }
        } else if (type == MotionNotify) {
            if (g_btn1_down) {
                int x = ev->u.keyButtonPointer.rootX;
                int y = ev->u.keyButtonPointer.rootY;
                g_last_x = x;
                g_last_y = y;
                send_touch(x, y, 1);
            }
        } else if (type == ButtonRelease) {
            BYTE button = ev->u.u.detail;
            if (button == 1) {
                int x = ev->u.keyButtonPointer.rootX;
                int y = ev->u.keyButtonPointer.rootY;
                uint64_t now = get_time_ms();
                uint64_t elapsed = now - g_press_time_ms;
                if (elapsed < MIN_PRESS_HOLD_MS) {
                    usleep((MIN_PRESS_HOLD_MS - elapsed) * 1000);
                }
                send_touch(x, y, 0);
                g_btn1_down = false;
            }
        }
    }

    XRecordFreeData(data);
}

static void sig_handler(int sig) {
    (void)sig;
    g_running = false;
    if (g_ctrl_dpy && g_ctx) {
        XRecordDisableContext(g_ctrl_dpy, g_ctx);
        XSync(g_ctrl_dpy, False);
    }
}

int main(int argc, char **argv) {
    (void)argc; (void)argv;
    setvbuf(stdout, NULL, _IOLBF, 0);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    const char *display_name = getenv("DISPLAY");
    if (!display_name || !*display_name) display_name = ":0";

    printf(LOG_TAG "Starting Remote Touch Bridge for DISPLAY=%s...\n", display_name);

    /* Setup UDP / UNIX Datagram client to touch_shim */
    g_sock_fd = socket(AF_UNIX, SOCK_DGRAM, 0);
    if (g_sock_fd < 0) {
        perror(LOG_TAG "socket(AF_UNIX)");
        return 1;
    }

    memset(&g_target_addr, 0, sizeof(g_target_addr));
    g_target_addr.sun_family = AF_UNIX;
    strncpy(g_target_addr.sun_path, TARGET_TOUCH_SOCK, sizeof(g_target_addr.sun_path) - 1);

    /* Connect to X Server */
    g_ctrl_dpy = XOpenDisplay(display_name);
    g_data_dpy = XOpenDisplay(display_name);
    if (!g_ctrl_dpy || !g_data_dpy) {
        fprintf(stderr, LOG_TAG "Error: Cannot open X Display %s\n", display_name);
        close(g_sock_fd);
        return 1;
    }

    /* Configure XRecord Range */
    XRecordRange *rr = XRecordAllocRange();
    if (!rr) {
        fprintf(stderr, LOG_TAG "Error: XRecordAllocRange failed\n");
        return 1;
    }
    rr->device_events.first = ButtonPress;
    rr->device_events.last  = MotionNotify;

    XRecordClientSpec cs = XRecordAllClients;
    g_ctx = XRecordCreateContext(g_ctrl_dpy, 0, &cs, 1, &rr, 1);
    XFree(rr);

    if (!g_ctx) {
        fprintf(stderr, LOG_TAG "Error: XRecordCreateContext failed\n");
        return 1;
    }

    XSync(g_ctrl_dpy, False);

    printf(LOG_TAG "Bridge active. Remote clicks in noVNC/VNC will now register on EP147 touch.\n");

    /* Main event loop: blocks in XRecordEnableContext */
    XRecordEnableContext(g_data_dpy, g_ctx, record_callback, NULL);

    /* Cleanup */
    if (g_ctrl_dpy && g_ctx) {
        XRecordFreeContext(g_ctrl_dpy, g_ctx);
        XCloseDisplay(g_ctrl_dpy);
    }
    if (g_data_dpy) XCloseDisplay(g_data_dpy);
    if (g_sock_fd >= 0) close(g_sock_fd);

    printf(LOG_TAG "Terminated cleanly.\n");
    return 0;
}
